import GCTCoverGrid
import GCTInstance
import GCTVariant
try:
    from typing import List, Optional
except:
    pass

class GCTT(object):

    # GCTT
    def __init__(
        self,
        FIELD_ID = None,
        TILING = 0,
        LEVEL = 0,
        X = 0,
        Y = 0,
        CHILD_MASK = 0,
        MAX_LEVEL = 255,
        REFINE = 0,
        GEOMETRIC_ERROR_M = 0.0,
        WEST_RAD = 0.0,
        SOUTH_RAD = 0.0,
        EAST_RAD = 0.0,
        NORTH_RAD = 0.0,
        MIN_HEIGHT_M = 0.0,
        MAX_HEIGHT_M = 0.0,
        ORIGIN_LON_RAD = 0.0,
        ORIGIN_LAT_RAD = 0.0,
        ORIGIN_HEIGHT_M = 0.0,
        ENU_TO_ECEF = None,
        FIELD_QUANTITY = 0,
        FIELD_QUANTITY_NAME = None,
        AMPLITUDE_UNITS = None,
        MASS_TOLERANCE = 0.0,
        VARIANTS = None,
        INSTANCES = None,
        COVER = None,
        VALID_TIME_MS = 0,
        INIT_TIME_MS = 0,
        LEAD_HOURS = 0.0,
        TIME_BASIS = 0,
        MODEL_CLASS = 0,
        MODEL_ID = None,
        SOURCE_FIELD_IDS = None,
        PRODUCER_PEER_ID = None,
        PRODUCER_VERSION = None,
        PRODUCER_NOTES = None,
        PRODUCED_AT_MS = 0,
        AUTHORING_SEED = 0,
        LICENSE_CLASS = 0,
        LICENSE_URL = None,
        CITATION = None,
    ):
        self.FIELD_ID = FIELD_ID  # type: Optional[str]
        self.TILING = TILING  # type: int
        self.LEVEL = LEVEL  # type: int
        self.X = X  # type: int
        self.Y = Y  # type: int
        self.CHILD_MASK = CHILD_MASK  # type: int
        self.MAX_LEVEL = MAX_LEVEL  # type: int
        self.REFINE = REFINE  # type: int
        self.GEOMETRIC_ERROR_M = GEOMETRIC_ERROR_M  # type: float
        self.WEST_RAD = WEST_RAD  # type: float
        self.SOUTH_RAD = SOUTH_RAD  # type: float
        self.EAST_RAD = EAST_RAD  # type: float
        self.NORTH_RAD = NORTH_RAD  # type: float
        self.MIN_HEIGHT_M = MIN_HEIGHT_M  # type: float
        self.MAX_HEIGHT_M = MAX_HEIGHT_M  # type: float
        self.ORIGIN_LON_RAD = ORIGIN_LON_RAD  # type: float
        self.ORIGIN_LAT_RAD = ORIGIN_LAT_RAD  # type: float
        self.ORIGIN_HEIGHT_M = ORIGIN_HEIGHT_M  # type: float
        self.ENU_TO_ECEF = ENU_TO_ECEF  # type: Optional[List[float]]
        self.FIELD_QUANTITY = FIELD_QUANTITY  # type: int
        self.FIELD_QUANTITY_NAME = FIELD_QUANTITY_NAME  # type: Optional[str]
        self.AMPLITUDE_UNITS = AMPLITUDE_UNITS  # type: Optional[str]
        self.MASS_TOLERANCE = MASS_TOLERANCE  # type: float
        self.VARIANTS = VARIANTS  # type: Optional[List[GCTVariant.GCTVariantT]]
        self.INSTANCES = INSTANCES  # type: Optional[List[GCTInstance.GCTInstanceT]]
        self.COVER = COVER  # type: Optional[GCTCoverGrid.GCTCoverGridT]
        self.VALID_TIME_MS = VALID_TIME_MS  # type: int
        self.INIT_TIME_MS = INIT_TIME_MS  # type: int
        self.LEAD_HOURS = LEAD_HOURS  # type: float
        self.TIME_BASIS = TIME_BASIS  # type: int
        self.MODEL_CLASS = MODEL_CLASS  # type: int
        self.MODEL_ID = MODEL_ID  # type: Optional[str]
        self.SOURCE_FIELD_IDS = SOURCE_FIELD_IDS  # type: Optional[List[Optional[str]]]
        self.PRODUCER_PEER_ID = PRODUCER_PEER_ID  # type: Optional[str]
        self.PRODUCER_VERSION = PRODUCER_VERSION  # type: Optional[str]
        self.PRODUCER_NOTES = PRODUCER_NOTES  # type: Optional[str]
        self.PRODUCED_AT_MS = PRODUCED_AT_MS  # type: int
        self.AUTHORING_SEED = AUTHORING_SEED  # type: int
        self.LICENSE_CLASS = LICENSE_CLASS  # type: int
        self.LICENSE_URL = LICENSE_URL  # type: Optional[str]
        self.CITATION = CITATION  # type: Optional[str]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpGct = GCT()
        tmpGct.Init(buf, pos)
        return cls.InitFromObj(tmpGct)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpGct):
        x = GCTT()
        x._UnPack(tmpGct)
        return x

    # GCTT
    def _UnPack(self, GCT):
        if GCT is None:
            return
        self.FIELD_ID = GCT.FIELD_ID()
        self.TILING = GCT.TILING()
        self.LEVEL = GCT.LEVEL()
        self.X = GCT.X()
        self.Y = GCT.Y()
        self.CHILD_MASK = GCT.CHILD_MASK()
        self.MAX_LEVEL = GCT.MAX_LEVEL()
        self.REFINE = GCT.REFINE()
        self.GEOMETRIC_ERROR_M = GCT.GEOMETRIC_ERROR_M()
        self.WEST_RAD = GCT.WEST_RAD()
        self.SOUTH_RAD = GCT.SOUTH_RAD()
        self.EAST_RAD = GCT.EAST_RAD()
        self.NORTH_RAD = GCT.NORTH_RAD()
        self.MIN_HEIGHT_M = GCT.MIN_HEIGHT_M()
        self.MAX_HEIGHT_M = GCT.MAX_HEIGHT_M()
        self.ORIGIN_LON_RAD = GCT.ORIGIN_LON_RAD()
        self.ORIGIN_LAT_RAD = GCT.ORIGIN_LAT_RAD()
        self.ORIGIN_HEIGHT_M = GCT.ORIGIN_HEIGHT_M()
        if not GCT.ENU_TO_ECEFIsNone():
            if np is None:
                self.ENU_TO_ECEF = []
                for i in range(GCT.ENU_TO_ECEFLength()):
                    self.ENU_TO_ECEF.append(GCT.ENU_TO_ECEF(i))
            else:
                self.ENU_TO_ECEF = GCT.ENU_TO_ECEFAsNumpy()
        self.FIELD_QUANTITY = GCT.FIELD_QUANTITY()
        self.FIELD_QUANTITY_NAME = GCT.FIELD_QUANTITY_NAME()
        self.AMPLITUDE_UNITS = GCT.AMPLITUDE_UNITS()
        self.MASS_TOLERANCE = GCT.MASS_TOLERANCE()
        if not GCT.VARIANTSIsNone():
            self.VARIANTS = []
            for i in range(GCT.VARIANTSLength()):
                if GCT.VARIANTS(i) is None:
                    self.VARIANTS.append(None)
                else:
                    gCTVariant_ = GCTVariant.GCTVariantT.InitFromObj(GCT.VARIANTS(i))
                    self.VARIANTS.append(gCTVariant_)
        if not GCT.INSTANCESIsNone():
            self.INSTANCES = []
            for i in range(GCT.INSTANCESLength()):
                if GCT.INSTANCES(i) is None:
                    self.INSTANCES.append(None)
                else:
                    gCTInstance_ = GCTInstance.GCTInstanceT.InitFromObj(GCT.INSTANCES(i))
                    self.INSTANCES.append(gCTInstance_)
        if GCT.COVER() is not None:
            self.COVER = GCTCoverGrid.GCTCoverGridT.InitFromObj(GCT.COVER())
        self.VALID_TIME_MS = GCT.VALID_TIME_MS()
        self.INIT_TIME_MS = GCT.INIT_TIME_MS()
        self.LEAD_HOURS = GCT.LEAD_HOURS()
        self.TIME_BASIS = GCT.TIME_BASIS()
        self.MODEL_CLASS = GCT.MODEL_CLASS()
        self.MODEL_ID = GCT.MODEL_ID()
        if not GCT.SOURCE_FIELD_IDSIsNone():
            self.SOURCE_FIELD_IDS = []
            for i in range(GCT.SOURCE_FIELD_IDSLength()):
                self.SOURCE_FIELD_IDS.append(GCT.SOURCE_FIELD_IDS(i))
        self.PRODUCER_PEER_ID = GCT.PRODUCER_PEER_ID()
        self.PRODUCER_VERSION = GCT.PRODUCER_VERSION()
        self.PRODUCER_NOTES = GCT.PRODUCER_NOTES()
        self.PRODUCED_AT_MS = GCT.PRODUCED_AT_MS()
        self.AUTHORING_SEED = GCT.AUTHORING_SEED()
        self.LICENSE_CLASS = GCT.LICENSE_CLASS()
        self.LICENSE_URL = GCT.LICENSE_URL()
        self.CITATION = GCT.CITATION()

    # GCTT
    def Pack(self, builder):
        if self.FIELD_ID is not None:
            FIELD_ID = builder.CreateString(self.FIELD_ID)
        if self.ENU_TO_ECEF is not None:
            if np is not None and type(self.ENU_TO_ECEF) is np.ndarray:
                ENU_TO_ECEF = builder.CreateNumpyVector(self.ENU_TO_ECEF)
            else:
                GCTStartENU_TO_ECEFVector(builder, len(self.ENU_TO_ECEF))
                for i in reversed(range(len(self.ENU_TO_ECEF))):
                    builder.PrependFloat64(self.ENU_TO_ECEF[i])
                ENU_TO_ECEF = builder.EndVector()
        if self.FIELD_QUANTITY_NAME is not None:
            FIELD_QUANTITY_NAME = builder.CreateString(self.FIELD_QUANTITY_NAME)
        if self.AMPLITUDE_UNITS is not None:
            AMPLITUDE_UNITS = builder.CreateString(self.AMPLITUDE_UNITS)
        if self.VARIANTS is not None:
            VARIANTSlist = []
            for i in range(len(self.VARIANTS)):
                VARIANTSlist.append(self.VARIANTS[i].Pack(builder))
            GCTStartVARIANTSVector(builder, len(self.VARIANTS))
            for i in reversed(range(len(self.VARIANTS))):
                builder.PrependUOffsetTRelative(VARIANTSlist[i])
            VARIANTS = builder.EndVector()
        if self.INSTANCES is not None:
            INSTANCESlist = []
            for i in range(len(self.INSTANCES)):
                INSTANCESlist.append(self.INSTANCES[i].Pack(builder))
            GCTStartINSTANCESVector(builder, len(self.INSTANCES))
            for i in reversed(range(len(self.INSTANCES))):
                builder.PrependUOffsetTRelative(INSTANCESlist[i])
            INSTANCES = builder.EndVector()
        if self.COVER is not None:
            COVER = self.COVER.Pack(builder)
        if self.MODEL_ID is not None:
            MODEL_ID = builder.CreateString(self.MODEL_ID)
        if self.SOURCE_FIELD_IDS is not None:
            SOURCE_FIELD_IDSlist = []
            for i in range(len(self.SOURCE_FIELD_IDS)):
                SOURCE_FIELD_IDSlist.append(builder.CreateString(self.SOURCE_FIELD_IDS[i]))
            GCTStartSOURCE_FIELD_IDSVector(builder, len(self.SOURCE_FIELD_IDS))
            for i in reversed(range(len(self.SOURCE_FIELD_IDS))):
                builder.PrependUOffsetTRelative(SOURCE_FIELD_IDSlist[i])
            SOURCE_FIELD_IDS = builder.EndVector()
        if self.PRODUCER_PEER_ID is not None:
            PRODUCER_PEER_ID = builder.CreateString(self.PRODUCER_PEER_ID)
        if self.PRODUCER_VERSION is not None:
            PRODUCER_VERSION = builder.CreateString(self.PRODUCER_VERSION)
        if self.PRODUCER_NOTES is not None:
            PRODUCER_NOTES = builder.CreateString(self.PRODUCER_NOTES)
        if self.LICENSE_URL is not None:
            LICENSE_URL = builder.CreateString(self.LICENSE_URL)
        if self.CITATION is not None:
            CITATION = builder.CreateString(self.CITATION)
        GCTStart(builder)
        if self.FIELD_ID is not None:
            GCTAddFIELD_ID(builder, FIELD_ID)
        GCTAddTILING(builder, self.TILING)
        GCTAddLEVEL(builder, self.LEVEL)
        GCTAddX(builder, self.X)
        GCTAddY(builder, self.Y)
        GCTAddCHILD_MASK(builder, self.CHILD_MASK)
        GCTAddMAX_LEVEL(builder, self.MAX_LEVEL)
        GCTAddREFINE(builder, self.REFINE)
        GCTAddGEOMETRIC_ERROR_M(builder, self.GEOMETRIC_ERROR_M)
        GCTAddWEST_RAD(builder, self.WEST_RAD)
        GCTAddSOUTH_RAD(builder, self.SOUTH_RAD)
        GCTAddEAST_RAD(builder, self.EAST_RAD)
        GCTAddNORTH_RAD(builder, self.NORTH_RAD)
        GCTAddMIN_HEIGHT_M(builder, self.MIN_HEIGHT_M)
        GCTAddMAX_HEIGHT_M(builder, self.MAX_HEIGHT_M)
        GCTAddORIGIN_LON_RAD(builder, self.ORIGIN_LON_RAD)
        GCTAddORIGIN_LAT_RAD(builder, self.ORIGIN_LAT_RAD)
        GCTAddORIGIN_HEIGHT_M(builder, self.ORIGIN_HEIGHT_M)
        if self.ENU_TO_ECEF is not None:
            GCTAddENU_TO_ECEF(builder, ENU_TO_ECEF)
        GCTAddFIELD_QUANTITY(builder, self.FIELD_QUANTITY)
        if self.FIELD_QUANTITY_NAME is not None:
            GCTAddFIELD_QUANTITY_NAME(builder, FIELD_QUANTITY_NAME)
        if self.AMPLITUDE_UNITS is not None:
            GCTAddAMPLITUDE_UNITS(builder, AMPLITUDE_UNITS)
        GCTAddMASS_TOLERANCE(builder, self.MASS_TOLERANCE)
        if self.VARIANTS is not None:
            GCTAddVARIANTS(builder, VARIANTS)
        if self.INSTANCES is not None:
            GCTAddINSTANCES(builder, INSTANCES)
        if self.COVER is not None:
            GCTAddCOVER(builder, COVER)
        GCTAddVALID_TIME_MS(builder, self.VALID_TIME_MS)
        GCTAddINIT_TIME_MS(builder, self.INIT_TIME_MS)
        GCTAddLEAD_HOURS(builder, self.LEAD_HOURS)
        GCTAddTIME_BASIS(builder, self.TIME_BASIS)
        GCTAddMODEL_CLASS(builder, self.MODEL_CLASS)
        if self.MODEL_ID is not None:
            GCTAddMODEL_ID(builder, MODEL_ID)
        if self.SOURCE_FIELD_IDS is not None:
            GCTAddSOURCE_FIELD_IDS(builder, SOURCE_FIELD_IDS)
        if self.PRODUCER_PEER_ID is not None:
            GCTAddPRODUCER_PEER_ID(builder, PRODUCER_PEER_ID)
        if self.PRODUCER_VERSION is not None:
            GCTAddPRODUCER_VERSION(builder, PRODUCER_VERSION)
        if self.PRODUCER_NOTES is not None:
            GCTAddPRODUCER_NOTES(builder, PRODUCER_NOTES)
        GCTAddPRODUCED_AT_MS(builder, self.PRODUCED_AT_MS)
        GCTAddAUTHORING_SEED(builder, self.AUTHORING_SEED)
        GCTAddLICENSE_CLASS(builder, self.LICENSE_CLASS)
        if self.LICENSE_URL is not None:
            GCTAddLICENSE_URL(builder, LICENSE_URL)
        if self.CITATION is not None:
            GCTAddCITATION(builder, CITATION)
        GCT = GCTEnd(builder)
        return GCT
